package com.bank.virt;

import java.util.logging.Logger;

// The physical host: one kernel, fixed total memory (MB).
public class Host {
    private static final Logger log = Logger.getLogger(Host.class.getName());
    private final int totalMemoryMb;
    private int usedMemoryMb;

    public Host(int totalMemoryMb) { this.totalMemoryMb = totalMemoryMb; }

    public boolean allocate(int mb, String who) {
        if (usedMemoryMb + mb > totalMemoryMb) {
            log.warning(() -> "Host OUT OF MEMORY: cannot give " + mb + "MB to " + who);
            return false;
        }
        usedMemoryMb += mb;
        log.info(() -> who + " allocated " + mb + "MB (host used " + usedMemoryMb
                + "/" + totalMemoryMb + "MB)");
        return true;
    }

    public String sharedKernel() { return "host-linux-kernel-6.1"; }
}
