package com.bank.virt;

import java.util.logging.Logger;

// A VM: boots its OWN guest OS via the hypervisor. Heavy + slow + strong isolation.
public class VirtualMachine implements Workload {
    private static final Logger log = Logger.getLogger(VirtualMachine.class.getName());
    private static final int GUEST_OS_OVERHEAD_MB = 1024; // its own kernel + services
    private final String name;
    private final int appMemoryMb;
    private final Host host;

    public VirtualMachine(String name, int appMemoryMb, Host host) {
        this.name = name;
        this.appMemoryMb = appMemoryMb;
        this.host = host;
    }

    @Override public void start() {
        log.info(() -> "VM '" + name + "' booting full guest OS on hypervisor...");
        host.allocate(totalMemoryFootprintMb(), "VM:" + name);
        log.info(() -> "VM '" + name + "' ready (own kernel, not host kernel)");
    }
    @Override public int totalMemoryFootprintMb() { return GUEST_OS_OVERHEAD_MB + appMemoryMb; }
    @Override public long startupMillis()         { return 25000; } // tens of seconds
    @Override public String isolationBoundary()   { return "hypervisor (strong)"; }
}
