package com.bank.virt;

import java.util.logging.Logger;

// A container: shares host kernel, isolated by namespaces, limited by cgroups.
public class Container implements Workload {
    private static final Logger log = Logger.getLogger(Container.class.getName());
    private final String name;
    private final int appMemoryMb;
    private final int cgroupLimitMb; // cgroup memory cap
    private final Host host;

    public Container(String name, int appMemoryMb, int cgroupLimitMb, Host host) {
        this.name = name;
        this.appMemoryMb = appMemoryMb;
        this.cgroupLimitMb = cgroupLimitMb;
        this.host = host;
    }

    @Override public void start() {
        log.info(() -> "Container '" + name + "' using host kernel " + host.sharedKernel()
                + " (namespaces for isolation)");
        // cgroup enforces that the container cannot exceed its limit.
        int request = Math.min(appMemoryMb, cgroupLimitMb);
        if (appMemoryMb > cgroupLimitMb) {
            log.warning(() -> "Container '" + name + "' capped by cgroup at "
                    + cgroupLimitMb + "MB (wanted " + appMemoryMb + "MB)");
        }
        host.allocate(request, "Container:" + name);
        log.info(() -> "Container '" + name + "' ready in milliseconds");
    }
    @Override public int totalMemoryFootprintMb() { return Math.min(appMemoryMb, cgroupLimitMb); }
    @Override public long startupMillis()         { return 80; } // milliseconds
    @Override public String isolationBoundary()   { return "namespaces + cgroups (thinner)"; }
}
