package com.bank.virt;

import java.util.List;
import java.util.logging.*;

public class VmVsContainerDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new VirtLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(VmVsContainerDemo.class.getName());
        Host host = new Host(8192); // 8 GB host

        log.info("=== VMs: each boots a full guest OS (heavy) ===");
        List<Workload> vms = List.of(
                new VirtualMachine("transfer-vm-1", 512, host),
                new VirtualMachine("transfer-vm-2", 512, host));
        vms.forEach(Workload::start);
        report(log, vms.get(0));

        log.info("=== Containers: share host kernel (light, dense) ===");
        List<Workload> containers = List.of(
                new Container("transfer-c1", 512, 768, host),
                new Container("transfer-c2", 512, 768, host),
                new Container("transfer-c3", 512, 768, host),
                new Container("greedy-c4", 4096, 768, host)); // tries to over-use
        containers.forEach(Workload::start);
        report(log, containers.get(0));
    }

    static void report(Logger log, Workload w) {
        log.info("  footprint=" + w.totalMemoryFootprintMb() + "MB  startup="
                + w.startupMillis() + "ms  isolation=" + w.isolationBoundary());
    }
}

// ─── Would be in VirtLogFormatter.java in a real project ───
class VirtLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
